from z3 import *

def solve():
    V = 19
    E = [[Bool(f"e_{i}_{j}") if i < j else None for j in range(V)] for i in range(V)]

    def edge(i, j):
        if i < j: return E[i][j]
        if i > j: return E[j][i]
        return False

    s = Solver()

    # At least 25 edges
    s.add(Sum([If(E[i][j], 1, 0) for i in range(V) for j in range(i+1, V)]) >= 25)

    # Girth >= 5
    # No 3-cycles
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                s.add(Not(And(edge(i, j), edge(j, k), edge(i, k))))

    # No 4-cycles
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                for l in range(k+1, V):
                    # 4-cycles involving i, j, k, l
                    # Possible orders:
                    # i-j-k-l-i
                    s.add(Not(And(edge(i, j), edge(j, k), edge(k, l), edge(l, i))))
                    # i-j-l-k-i
                    s.add(Not(And(edge(i, j), edge(j, l), edge(l, k), edge(k, i))))
                    # i-k-j-l-i
                    s.add(Not(And(edge(i, k), edge(k, j), edge(j, l), edge(l, i))))

    # 5-colorable
    C = [Int(f"c_{i}") for i in range(V)]
    for i in range(V):
        s.add(C[i] >= 0, C[i] < 5)
    for i in range(V):
        for j in range(i+1, V):
            s.add(Implies(edge(i, j), C[i] != C[j]))

    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(V):
            for j in range(i+1, V):
                if is_true(m[E[i][j]]):
                    edges.append((i, j))
        print(edges)
    else:
        print("UNSAT")

solve()

