adj = {i: set() for i in range(19)}
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

def has_cycle(length):
    import itertools
    for p in itertools.permutations(range(19), length):
        if all(p[i+1] in adj[p[i]] for i in range(length-1)) and p[0] in adj[p[-1]]:
            return True
    return False

